class Solution:
    def countWays(self, word1: str, word2: str, target: str) -> int:
        MOD = 10**9 + 7
        n, m, T = len(word1), len(word2), len(target)
        g = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(T + 1)]
        for i in range(n + 1):
            for j in range(m + 1):
                g[0][i][j] = 1
        for t in range(1, T + 1):
            c = target[t - 1]
            gt, gp = g[t], g[t - 1]
            for i in range(n + 1):
                for j in range(m + 1):
                    v = gt[i - 1][j] + gt[i][j - 1] - gt[i - 1][j - 1]
                    if i > 0 and word1[i - 1] == c:
                        v += gp[i - 1][j]
                    if j > 0 and word2[j - 1] == c:
                        v += gp[i][j - 1]
                    gt[i][j] = v % MOD
        def numDistinct(s, tg):
            dp = [0] * (len(tg) + 1)
            dp[0] = 1
            for ch in s:
                for k in range(len(tg), 0, -1):
                    if tg[k - 1] == ch:
                        dp[k] = (dp[k] + dp[k - 1]) % MOD
            return dp[len(tg)]
        return (g[T][n][m] - numDistinct(word1, target) - numDistinct(word2, target)) % MOD

