public:
    int countWays(string word1, string word2, string target) {
        const long long MOD = 1e9 + 7;
        int n = word1.size(), m = word2.size(), T = target.size();
        vector<vector<vector<long long>>> g(T + 1,
            vector<vector<long long>>(n + 1, vector<long long>(m + 1, 0)));
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= m; j++) g[0][i][j] = 1;
        for (int t = 1; t <= T; t++) {
            char c = target[t - 1];
            for (int i = 0; i <= n; i++)
                for (int j = 0; j <= m; j++) {
                    long long v = g[t][i - 1][j] + g[t][i][j - 1] - g[t][i - 1][j - 1];
                    if (i > 0 && word1[i - 1] == c) v += g[t - 1][i - 1][j];
                    if (j > 0 && word2[j - 1] == c) v += g[t - 1][i][j - 1];
                    g[t][i][j] = ((v % MOD) + MOD) % MOD;
                }
        }
        auto numDistinct = [&](const string& s, const string& tg) {
            vector<long long> dp(tg.size() + 1, 0);
            dp[0] = 1;
            for (char ch : s)
                for (int k = tg.size(); k >= 1; k--)
                    if (tg[k - 1] == ch) dp[k] = (dp[k] + dp[k - 1]) % MOD;
            return dp[tg.size()];
        };
        long long ans = g[T][n][m] - numDistinct(word1, target) - numDistinct(word2, target);
        return (int)((ans % MOD + MOD) % MOD);
    }
};

